-- 단위 표시 정리 (required_qty는 base 단위 → unit을 base_unit으로 통일)
UPDATE Recipe_Ingredient ri JOIN Ingredient_Master im ON ri.ingredient_id=im.ingredient_id
   SET ri.unit = im.base_unit WHERE ri.unit <> im.base_unit;
